// EVERGREEN PARTNERSHIP ENGINE — STAGE 2: ENRICH AND VERIFY — CONFIG
// Everything you might want to change lives in this one node. Nothing else in this
// workflow needs editing.
//
// Any key left blank means that step is SKIPPED, not that the run fails. That is what
// lets this be demonstrated on a screen-share before a single credential exists.

// ---------------------------------------------------------------- Your working sheet
// The id is the long code in the sheet's web address:
// docs.google.com/spreadsheets/d/<THIS BIT>/edit
const SHEET_ID     = '';
const ORGS_TAB     = 'Organisations';   // the raw list, from scrapers and directories
const CONTACTS_TAB = 'Contacts';        // the enriched, verified output

// Column headings, exactly as they appear in row 1 of each tab.
const ORG_COLUMNS = {
  org_id:      'Org id',
  name:        'Organisation',
  category:    'Category',
  website:     'Website',
  county:      'County',
  city:        'City',
  state:       'State',
  phone:       'Phone',
  // Optional, and only used when Apollo is not configured: a name and address a scraper or
  // a researcher already put on the row.
  contact:       'Contact',
  contact_title: 'Contact title',
  contact_email: 'Contact email',
  source:      'Source',
  status:      'Status',
  enriched_at: 'Enriched at',
  contacts:    'Contacts found',
  notes:       'Notes'
};

const CONTACT_COLUMNS = {
  contact_id:   'Contact id',
  org_id:       'Org id',
  org_name:     'Organisation',
  category:     'Category',
  county:       'County',
  full_name:    'Full name',
  first_name:   'First name',
  title:        'Title',
  email:        'Email',
  email_status: 'Email status',
  verified_at:  'Verified at',
  phone:        'Phone',
  linkedin:     'LinkedIn',
  score:        'ICP score',
  tier:         'Tier',
  sending_list: 'Sending list',
  hold_reason:  'Hold reason',
  campaign:     'Campaign',
  pushed_at:    'Pushed at',
  updated_at:   'Last updated'
};

// ---------------------------------------------------------------- How much per run
const BATCH_SIZE           = 25;   // organisations enriched per run
const MAX_CONTACTS_PER_ORG = 3;    // more than this from one building reads as a blast
const REENRICH_AFTER_DAYS  = 90;   // an org already done is left alone for this long
const DAILY_CAP            = 200;  // hard ceiling on contacts pushed per run

// Only these org statuses are picked up. Anything else is treated as already handled.
const READY_STATUSES = ['', 'New', 'Ready', 'Re-enrich'];

// ---------------------------------------------------------------- Who we are looking for
// The segments in the brief. First rule whose words appear in the org name or the website
// wins, so put the more specific rule first.
const CATEGORY_RULES = [
  { category: 'Hospital / discharge planning',
    words: ['hospital', 'medical center', 'medical centre', 'health system', 'regional health',
            'discharge', 'inpatient', 'emergency department'] },
  { category: 'Addiction treatment',
    words: ['recovery', 'treatment center', 'treatment centre', 'detox', 'sober', 'substance',
            'rehab', 'opioid', 'addiction', 'withdrawal'] },
  { category: 'County social services',
    words: ['job and family services', 'jfs', 'county', 'department of', 'adamhs',
            'developmental disabilities', 'children services', 'public health'] },
  { category: 'Community non-profit',
    words: ['community action', 'united way', 'food bank', 'ministries', 'shelter', 'housing',
            'coalition', 'ymca', 'salvation army', 'foundation', 'nonprofit', 'non-profit'] },
  { category: 'Behavioral health provider',
    words: ['behavioral', 'behavioural', 'counseling', 'counselling', 'mental health',
            'psychiatric', 'wellness'] }
];

// Titles that can actually send a referral. The weight is the starting ICP score.
const TITLE_RULES = [
  { weight: 45, tier: 'A',
    words: ['discharge planner', 'discharge planning', 'director of case management',
            'case management director', 'transitions of care', 'utilization review',
            'utilisation review', 'social work director', 'director of social work',
            'care coordination manager'] },
  { weight: 40, tier: 'A',
    words: ['executive director', 'chief clinical', 'clinical director', 'director of nursing',
            'behavioral health director', 'director of behavioral', 'program director',
            'admissions director', 'director of admissions', 'county director'] },
  { weight: 30, tier: 'B',
    words: ['referral coordinator', 'intake coordinator', 'intake manager', 'care coordinator',
            'case manager', 'social worker', 'peer support', 'community outreach',
            'outreach coordinator', 'nurse manager', 'supervisor'] },
  { weight: 20, tier: 'B',
    words: ['director', 'manager', 'coordinator', 'administrator'] }
];

// Nobody in these roles can refer a patient. Dropped, not scored.
const EXCLUDE_TITLES = ['billing', 'accounts payable', 'recruiter', 'talent acquisition',
  'sales', 'account executive', 'marketing', 'it support', 'systems admin', 'volunteer',
  'intern', 'student', 'security'];

// A mailbox nobody owns. Held back — these are where bounce rates come from.
const ROLE_PREFIXES = ['info', 'admin', 'contact', 'office', 'hello', 'enquiries', 'inquiries',
  'support', 'billing', 'careers', 'jobs', 'hr', 'media', 'press', 'noreply', 'no-reply',
  'donate', 'volunteer', 'webmaster', 'postmaster'];

const MIN_ICP_SCORE = 35;    // below this a contact is kept in the sheet but not emailed
const REQUIRE_STATE = 'OH';  // blank to accept any state

// Never contact these, whatever else says otherwise. Domains or full addresses.
// Anything that replies "remove me" goes in here.
const SUPPRESSION = [
  'evergreenmentorship.org'
];

// ---------------------------------------------------------------- Apollo (people search)
// app.apollo.io -> Settings -> Integrations -> API. Blank = skip Apollo and use whatever
// contact details the raw list already carries.
const APOLLO_API_KEY = '';
const APOLLO_URL     = 'https://api.apollo.io/api/v1/mixed_people/search';

// ---------------------------------------------------------------- Email verification
// This is the KPI. Under 2% bounce is not a copywriting problem, it is this step.
// MillionVerifier by default; any verifier that returns a status string works.
const VERIFIER_API_KEY = '';
const VERIFIER_URL     = 'https://api.millionverifier.com/api/v3/';

// Which verdicts are allowed onto the sending list. Everything else is held.
const ACCEPT_STATUSES = ['ok', 'valid', 'deliverable'];
const RISKY_STATUSES  = ['catch_all', 'catch-all', 'accept_all', 'unknown', 'risky'];

// true = an address we could not verify is never emailed. Turning this off is how a
// campaign ends up at a 12% bounce rate and a burnt domain. Leave it true.
const HOLD_UNVERIFIED = true;

// Demo only. With no verifier key set, gives each address a deterministic fake verdict so
// the whole pipeline can be watched end to end before any account exists. While this is on
// the run is FORCED into preview — a made-up verdict can never reach a real campaign.
const DEMO_VERIFIER = false;

// ---------------------------------------------------------------- Optional AI classifier
// Only used on organisations the keyword rules could not place. Blank = keyword rules only,
// which is where most of them land anyway.
const AI_API_KEY = '';
const AI_URL     = 'https://api.anthropic.com/v1/messages';
const AI_MODEL   = 'claude-opus-5';

// ---------------------------------------------------------------- The sending engine
// Instantly: Settings -> Integrations -> API keys (a v2 key). Smartlead works the same way:
// change INSTANTLY_URL and the body built in "payload for the campaign".
const INSTANTLY_API_KEY     = '';
const INSTANTLY_URL         = 'https://api.instantly.ai/api/v2/leads';
const INSTANTLY_CAMPAIGN_ID = '';

// Optional: a different campaign per segment, so a hospital and a county office do not get
// the same email. Anything not listed here goes to INSTANTLY_CAMPAIGN_ID.
const CAMPAIGN_BY_CATEGORY = {
  // 'Hospital / discharge planning': 'campaign-uuid-here',
  // 'County social services':        'campaign-uuid-here'
};

// ---------------------------------------------------------------- Run summary
const ALERT_WEBHOOK_URL = '';   // Slack incoming webhook. Blank = no notification.

// ---------------------------------------------------------------- Safety switch
//   TEST_RUN true,  TEST_CAMPAIGN_ID blank -> PREVIEW. The sheet is written so you can read
//                                            every verdict and score, but nothing is pushed
//                                            to a campaign. Ships this way.
//   TEST_RUN true,  TEST_CAMPAIGN_ID set   -> TEST. Leads really are pushed, but to that
//                                            campaign instead of the live one.
//   TEST_RUN false                         -> LIVE.
const TEST_RUN         = true;
const TEST_CAMPAIGN_ID = '';

const DEMO_VERDICTS = DEMO_VERIFIER === true && VERIFIER_API_KEY.trim() === '';

let MODE = TEST_RUN !== true ? 'live'
  : (TEST_CAMPAIGN_ID.trim() !== '' ? 'test' : 'preview');

// Demo verdicts are not evidence. They cannot open the sending gate, whatever TEST_RUN says.
const FORCED_PREVIEW = DEMO_VERDICTS && MODE !== 'preview';
if (FORCED_PREVIEW) MODE = 'preview';

const CAMPAIGN_ID = MODE === 'test' ? TEST_CAMPAIGN_ID.trim() : INSTANTLY_CAMPAIGN_ID.trim();

return [{
  json: {
    sheet_id:        SHEET_ID,
    orgs_tab:        ORGS_TAB,
    contacts_tab:    CONTACTS_TAB,
    org_columns:     ORG_COLUMNS,
    contact_columns: CONTACT_COLUMNS,

    batch_size:           Number(BATCH_SIZE) || 25,
    max_contacts_per_org: Number(MAX_CONTACTS_PER_ORG) || 1,
    reenrich_after_days:  Number(REENRICH_AFTER_DAYS) || 90,
    daily_cap:            Number(DAILY_CAP) || 0,
    ready_statuses:       READY_STATUSES,

    category_rules: CATEGORY_RULES,
    title_rules:    TITLE_RULES,
    exclude_titles: EXCLUDE_TITLES,
    role_prefixes:  ROLE_PREFIXES,
    min_icp_score:  Number(MIN_ICP_SCORE) || 0,
    require_state:  REQUIRE_STATE.trim().toUpperCase(),
    suppression:    SUPPRESSION.map((s) => String(s).trim().toLowerCase()).filter(Boolean),

    apollo_api_key: APOLLO_API_KEY.trim(),
    apollo_url:     APOLLO_URL,

    verifier_api_key: VERIFIER_API_KEY.trim(),
    verifier_url:     VERIFIER_URL,
    accept_statuses:  ACCEPT_STATUSES.map((s) => s.toLowerCase()),
    risky_statuses:   RISKY_STATUSES.map((s) => s.toLowerCase()),
    hold_unverified:  HOLD_UNVERIFIED !== false,

    ai_api_key: AI_API_KEY.trim(),
    ai_url:     AI_URL,
    ai_model:   AI_MODEL,

    instantly_api_key:    INSTANTLY_API_KEY.trim(),
    instantly_url:        INSTANTLY_URL,
    campaign_id:          CAMPAIGN_ID,
    campaign_by_category: CAMPAIGN_BY_CATEGORY,

    alert_webhook_url: ALERT_WEBHOOK_URL.trim(),

    // derived flags — the gates read these, never the raw constants
    mode:         MODE,
    preview_only: MODE === 'preview',
    test_send:    MODE === 'test',
    live_send:    MODE === 'live',
    push_enabled: MODE !== 'preview' && INSTANTLY_API_KEY.trim() !== '' && CAMPAIGN_ID !== '',

    apollo_enabled:   APOLLO_API_KEY.trim() !== '',
    verifier_enabled: VERIFIER_API_KEY.trim() !== '',
    ai_enabled:       AI_API_KEY.trim() !== '',
    alert_enabled:    ALERT_WEBHOOK_URL.trim() !== '',
    demo_verdicts:    DEMO_VERDICTS,
    forced_preview:   FORCED_PREVIEW
  }
}];

// Decide which organisations this run works on.
//
// Three things happen here and nowhere else: rows already enriched recently are skipped,
// the same organisation appearing twice in the raw list is collapsed to one, and the run is
// capped at BATCH_SIZE. The cap is what keeps Apollo credits and verifier spend predictable
// — a scraper that dumps 4,000 rows in overnight does not turn into 4,000 API calls at 07:00.
const cfg = $('config').first().json;
const col = cfg.org_columns;
const rows = $input.all().map((i) => i.json);

const ready = (cfg.ready_statuses || []).map((s) => String(s).trim().toLowerCase());
const staleMs = Number(cfg.reenrich_after_days || 90) * 24 * 60 * 60 * 1000;
const now = Date.now();

const key = (row) => {
  const site = String(row[col.website] || '').toLowerCase()
    .replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '').trim();
  if (site) return 'd:' + site;
  return 'n:' + String(row[col.name] || '').toLowerCase().replace(/[^a-z0-9]/g, '');
};

const seen = new Set();
const picked = [];
const skipped = { not_ready: 0, too_recent: 0, duplicate: 0, no_name: 0 };

for (const row of rows) {
  const name = String(row[col.name] || '').trim();
  if (!name) { skipped.no_name++; continue; }

  const status = String(row[col.status] || '').trim().toLowerCase();
  if (ready.length && !ready.includes(status)) { skipped.not_ready++; continue; }

  const enriched = String(row[col.enriched_at] || '').trim();
  if (enriched && status !== 're-enrich') {
    const when = Date.parse(enriched);
    if (!isNaN(when) && now - when < staleMs) { skipped.too_recent++; continue; }
  }

  const k = key(row);
  if (seen.has(k)) { skipped.duplicate++; continue; }
  seen.add(k);

  picked.push(row);
  if (picked.length >= Number(cfg.batch_size || 25)) break;
}

// The read node has alwaysOutputData on, so a tab holding only a header row arrives here as
// one empty item rather than as nothing at all. Telling those two apart is the difference
// between "your sheet is empty" and "your workflow is broken".
const emptyTab = rows.length === 0
  || rows.every((r) => Object.keys(r).filter((k) => String(r[k] || '').trim() !== '').length === 0);

const stats = {
  _rows_in_sheet: emptyTab ? 0 : rows.length,
  _picked: picked.length,
  _skipped: skipped,
  _sheet_empty: emptyTab,
  _tab: cfg.orgs_tab,
  _has_work: picked.length > 0
};

if (!picked.length) return [{ json: stats }];

return picked.map((row, idx) => ({
  json: Object.assign({}, stats, {
    _row: row,
    // A stable id, so a re-run updates the same row instead of appending a second one.
    org_id: String(row[col.org_id] || '').trim()
      || 'ORG-' + key(row).replace(/[^a-z0-9]/g, '').slice(0, 24) || 'ORG-' + (idx + 1)
  })
}));

// Nothing in the raw list needs work: every row is already enriched, a duplicate, or not
// marked ready. The run ends here on purpose and says which, so an empty morning is
// distinguishable from a broken morning.
//
// The empty-tab case is called out separately because it is the one that looks like a bug.
// A tab with only a header row would otherwise end the run at the Sheets node with a green
// tick and no explanation at all.
const s = $input.first().json;
const skipped = s._skipped || {};

const why = s._sheet_empty
  ? 'The "' + (s._tab || 'Organisations') + '" tab has no data rows. Headings alone are not '
    + 'enough — paste some organisations in below row 1, or check that ORGS_TAB in config '
    + 'matches the tab name exactly.'
  : 'Every row is either already enriched, a duplicate, or not marked ready. Set Status to '
    + 'Re-enrich on anything you want redone.';

return [{
  json: {
    _outcome: s._sheet_empty ? 'the sheet is empty' : 'nothing to enrich',
    tab: s._tab || '',
    rows_in_sheet: s._rows_in_sheet || 0,
    already_enriched_recently: skipped.too_recent || 0,
    not_marked_ready: skipped.not_ready || 0,
    duplicates_in_the_list: skipped.duplicate || 0,
    rows_with_no_name: skipped.no_name || 0,
    _next_step: why
  }
}];

// Turn a scraped row into something a data provider can be asked about.
//
// Apollo is only as good as the domain you hand it. "www.MtCarmelHealth.com/about" and
// "https://mtcarmelhealth.com" are the same building, and asking twice costs twice. The
// category is decided by the keyword rules in config; anything the rules cannot place is
// flagged _needs_ai and the optional classifier picks it up.
//
// The two provider payloads are built here rather than inside the HTTP nodes, so the prompt
// and the search are readable — and editable — without opening a body expression.
const cfg = $('config').first().json;
const col = cfg.org_columns;

const text = (v) => String(v == null ? '' : v).trim();
const categories = (cfg.category_rules || []).map((r) => r.category);

// Only the specific titles are searched on. The catch-all "director"/"manager" rule exists to
// score whoever comes back, not to ask Apollo for every manager in a hospital.
const searchTitles = [];
for (const rule of (cfg.title_rules || []).slice(0, 3)) {
  for (const w of rule.words || []) if (searchTitles.length < 25) searchTitles.push(w);
}

return $input.all().map((entry) => {
  const item = entry.json;
  const row = item._row || {};

  const name = text(row[col.name]);

  const domain = text(row[col.website]).toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/[/?#].*$/, '')
    .replace(/[^a-z0-9.-]/g, '');

  const haystack = (name + ' ' + domain).toLowerCase();

  // A category already typed into the sheet by a human beats any rule here.
  let category = text(row[col.category]);
  let matchedOn = '';
  let confident = category !== '';

  if (!category) {
    for (const rule of cfg.category_rules || []) {
      const hit = (rule.words || []).find((w) => haystack.includes(String(w).toLowerCase()));
      if (hit) { category = rule.category; matchedOn = hit; confident = true; break; }
    }
  }

  if (!category) { category = 'Unclassified'; confident = false; }

  const aiSystem = 'You classify Ohio health and social-service organisations for a referral '
    + 'partnership programme. Answer with one JSON object and nothing else: '
    + '{"category": "<one of the listed categories, or Other>", "confidence": <0-1>, '
    + '"reason": "<12 words max>"}. Never invent a category that is not listed.';

  const aiUser = 'Categories: ' + categories.join(' | ') + ' | Other\n\n'
    + 'Organisation: ' + (name || '(no name)') + '\n'
    + 'Website: ' + (domain || '(none)') + '\n'
    + 'City/County: ' + [text(row[col.city]), text(row[col.county])].filter(Boolean).join(', ')
    + '\n\nWhich category is it?';

  const apolloBody = {
    q_organization_domains_list: domain ? [domain] : [],
    q_organization_name: domain ? undefined : name,
    person_titles: searchTitles,
    person_locations: cfg.require_state === 'OH' ? ['Ohio, US'] : undefined,
    page: 1,
    per_page: Math.max(Number(cfg.max_contacts_per_org || 3) * 3, 5)
  };

  return {
    json: {
      org_id:   item.org_id,
      org_name: name,
      domain:   domain,
      category: category,
      county:   text(row[col.county]),
      city:     text(row[col.city]),
      state:    text(row[col.state]).toUpperCase().slice(0, 2),
      phone:    text(row[col.phone]),
      source:   text(row[col.source]) || 'sheet',

      // whatever the raw list already knew — the fallback when Apollo is not configured
      _row: row,

      _category_matched_on: matchedOn,
      _category_confident:  confident,
      // Only an unclassified org is worth an AI call. The rest already have an answer.
      _needs_ai: !confident && cfg.ai_enabled === true,
      _domain_missing: domain === '',

      _ai_system: aiSystem,
      _ai_user:   aiUser,
      // JSON round-trip drops the undefined keys, which Apollo would otherwise reject.
      _apollo_body: JSON.parse(JSON.stringify(apolloBody))
    }
  };
});

// Read the classifier's answer back onto the organisation.
//
// Two rules. The model may only pick a category that exists in config — anything else is
// treated as Unclassified rather than quietly inventing a segment. And a failed or
// unparseable call leaves the organisation exactly as the keyword rules left it, so the run
// continues; an AI outage is not an outage of the pipeline.
const cfg = $('config').first().json;
const allowed = (cfg.category_rules || []).map((r) => r.category);
const src = $('AI classification needed?');
const replies = $input.all();

const orgFor = (i) => {
  try { return src.itemMatching(i).json; } catch (e) { /* fall through */ }
  return (src.all(0)[i] || src.all()[i] || { json: {} }).json;
};

// Claude returns content blocks; with thinking on, the answer is not always block 0.
const firstText = (body) => {
  const blocks = (body && body.content) || [];
  const block = blocks.find((b) => b && b.type === 'text' && String(b.text || '').trim());
  return block ? String(block.text) : '';
};

const parse = (raw) => {
  const s = String(raw || '').trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try { return JSON.parse(s.slice(start, end + 1)); } catch (e) { return null; }
};

return replies.map((reply, i) => {
  const org = orgFor(i);
  const body = reply.json || {};
  const answer = parse(firstText(body));

  const category = answer && allowed.includes(String(answer.category)) ? String(answer.category) : '';
  const confidence = answer && isFinite(Number(answer.confidence)) ? Number(answer.confidence) : 0;
  const usable = category !== '' && confidence >= 0.5;

  return {
    json: Object.assign({}, org, {
      category: usable ? category : (org.category || 'Unclassified'),
      _category_matched_on: usable ? 'ai' : (org._category_matched_on || ''),
      _category_confident: usable ? true : Boolean(org._category_confident),
      _ai_called: true,
      _ai_answer: answer ? (answer.reason || '') : '',
      _ai_confidence: confidence,
      _ai_failed: answer === null,
      _ai_error: body.error ? String(body.error.message || body.error.type || 'error') : ''
    })
  };
});

// No AI key set, or the keyword rules already placed this organisation confidently.
// Either way it carries on with the category it has — this branch exists so the canvas
// shows where those items went instead of them appearing to vanish.
return $input.all().map((i) => ({
  json: Object.assign({}, i.json, { _ai_called: false })
}));

// Turn one Apollo response per organisation into one item per person.
//
// The detail that matters: Apollo hands back placeholders like
// "user@example.com" for people whose address costs a credit to reveal. Treated
// as a real address, those are a guaranteed hard bounce. They are dropped here, and the
// organisation is written back as "No contact found" rather than silently looking enriched.
const cfg = $('config').first().json;
const src = $('Apollo configured?');
const replies = $input.all();

const orgFor = (i) => {
  try { return src.itemMatching(i).json; } catch (e) { /* fall through */ }
  return (src.all(0)[i] || src.all()[i] || { json: {} }).json;
};

const placeholder = (email) => {
  const e = String(email || '').toLowerCase();
  return e === '' || e.includes('email_not_unlocked') || e.includes('not_unlocked')
    || e.startsWith('email_') || e.includes('domain.com');
};

const out = [];

replies.forEach((reply, i) => {
  const org = orgFor(i);
  const body = reply.json || {};
  const people = [].concat(body.people || [], body.contacts || []);

  const usable = [];
  let hidden = 0;

  for (const p of people) {
    const email = String(p.email || '').trim().toLowerCase();
    if (placeholder(email)) { hidden++; continue; }
    usable.push({ p: p, email: email });
    if (usable.length >= Number(cfg.max_contacts_per_org || 3)) break;
  }

  if (!usable.length) {
    out.push({
      json: Object.assign({}, org, {
        _no_contact: true,
        _hold_reason: hidden ? 'Apollo has ' + hidden + ' people, no unlocked email' : 'no contact found',
        _apollo_people: people.length,
        _apollo_hidden: hidden,
        _apollo_error: body.error ? String(body.error) : (body.message || '')
      })
    });
    return;
  }

  usable.forEach((u, n) => {
    const p = u.p;
    const phones = [].concat(p.phone_numbers || []);
    out.push({
      json: Object.assign({}, org, {
        _no_contact: false,
        contact_id: org.org_id + '-' + (n + 1),
        full_name: String(p.name || [p.first_name, p.last_name].filter(Boolean).join(' ')).trim(),
        first_name: String(p.first_name || '').trim(),
        title: String(p.title || '').trim(),
        email: u.email,
        contact_phone: String((phones[0] && (phones[0].sanitized_number || phones[0].raw_number)) || '').trim(),
        linkedin: String(p.linkedin_url || '').trim(),
        // Apollo's own guess. Useful, but it is not verification and is never treated as such.
        provider_email_status: String(p.email_status || '').trim(),
        _apollo_people: people.length,
        _apollo_hidden: hidden,
        _from: 'apollo'
      })
    });
  });
});

return out;

// No Apollo key. Rather than fail, fall back to whatever contact details the raw list
// already carries — scraped staff pages and county directories usually give a name, a title
// and an address, which is enough to score and verify. This is also the branch the whole
// workflow runs on during a demo, before any account exists.
const cfg = $('config').first().json;
const col = cfg.org_columns;

return $input.all().map((item) => {
  const org = item.json;
  const row = org._row || {};

  const email = String(row[col.contact_email] || '').trim().toLowerCase();
  const name = String(row[col.contact] || '').trim();
  const title = String(row[col.contact_title] || '').trim();

  if (!email) {
    return {
      json: Object.assign({}, org, {
        _no_contact: true,
        _hold_reason: 'no contact on the row (Apollo not configured)',
        _from: 'sheet'
      })
    };
  }

  return {
    json: Object.assign({}, org, {
      _no_contact: false,
      contact_id: org.org_id + '-1',
      full_name: name,
      first_name: name.split(/\s+/)[0] || '',
      title: title,
      email: email,
      contact_phone: String(row[col.phone] || '').trim(),
      linkedin: '',
      // Nothing from a scrape is treated as verified. That is the verifier's job.
      provider_email_status: '',
      _from: 'sheet'
    })
  };
});

// Score every contact against the ideal profile, so the caller's day is spent on the people
// who can actually make a referral.
//
// The score is deliberately boring arithmetic, not a black box: title weight from config,
// plus small bonuses for a direct phone number and a segment we know the offer lands in.
// When Zak asks "why is this person a 78", the answer is four numbers you can point at.
const cfg = $('config').first().json;

const titleRules = cfg.title_rules || [];
const excluded = (cfg.exclude_titles || []).map((t) => String(t).toLowerCase());

// Segments where a no-cost Medicaid telehealth referral is closest to a live need.
const CATEGORY_BONUS = {
  'Hospital / discharge planning': 12,
  'Addiction treatment': 10,
  'County social services': 8,
  'Behavioral health provider': 6,
  'Community non-profit': 4
};

return $input.all().map((item) => {
  const c = item.json;

  if (c._no_contact) {
    return { json: Object.assign({}, c, { score: 0, tier: '-', _verifiable: false }) };
  }

  const title = String(c.title || '').toLowerCase();
  const hitExcluded = excluded.find((t) => title.includes(t));

  if (hitExcluded) {
    return {
      json: Object.assign({}, c, {
        score: 0, tier: 'X', _verifiable: false,
        _hold_reason: 'excluded title (' + hitExcluded + ')'
      })
    };
  }

  let weight = 0;
  let tier = 'C';
  let matchedTitle = '';
  for (const rule of titleRules) {
    const hit = (rule.words || []).find((w) => title.includes(String(w).toLowerCase()));
    if (hit) { weight = Number(rule.weight) || 0; tier = rule.tier || 'C'; matchedTitle = hit; break; }
  }

  const categoryBonus = Number(CATEGORY_BONUS[c.category] || 0);
  const phoneBonus = String(c.contact_phone || c.phone || '').trim() ? 8 : 0;
  const linkedinBonus = String(c.linkedin || '').trim() ? 4 : 0;
  const namedBonus = String(c.first_name || '').trim() ? 6 : 0;

  const score = Math.max(0, Math.min(100, weight + categoryBonus + phoneBonus + linkedinBonus + namedBonus));

  return {
    json: Object.assign({}, c, {
      score: score,
      tier: score >= 70 ? 'A' : (score >= Number(cfg.min_icp_score || 35) ? tier : 'C'),
      _score_parts: {
        title: weight, title_matched: matchedTitle, category: categoryBonus,
        phone: phoneBonus, linkedin: linkedinBonus, named: namedBonus
      },
      // Only a real address on a scorable person is worth a verifier credit.
      _verifiable: String(c.email || '').includes('@') && cfg.verifier_enabled === true
    })
  };
});

// Read the verifier's verdict back onto the contact. This node is the bounce-rate KPI.
//
// It fails closed, and that is the whole point: a call that times out, 402s on credits or
// returns something unrecognised becomes "unknown", which is held back, not sent. Every
// other outcome in a cold-email system can be fixed later; a burnt sending domain cannot.
const cfg = $('config').first().json;
const accept = cfg.accept_statuses || [];
const risky = cfg.risky_statuses || [];
const src = $('verification possible?');
const replies = $input.all();

const contactFor = (i) => {
  try { return src.itemMatching(i).json; } catch (e) { /* fall through */ }
  return (src.all(0)[i] || src.all()[i] || { json: {} }).json;
};

const stamp = new Date().toISOString().slice(0, 16).replace('T', ' ');

return replies.map((reply, i) => {
  const contact = contactFor(i);
  const body = reply.json || {};

  // MillionVerifier uses "result"; NeverBounce and ZeroBounce use "result"/"status".
  const raw = String(body.result || body.status || body.state || '').toLowerCase().trim();
  const status = raw || 'unknown';

  const verdict = accept.includes(status) ? 'accepted'
    : (risky.includes(status) ? 'risky' : 'rejected');

  return {
    json: Object.assign({}, contact, {
      email_status: status,
      _verdict: verdict,
      _verified: verdict === 'accepted',
      _verified_at: stamp,
      _verifier_role_flag: body.role === true || body.role === 'true',
      _verifier_raw: raw ? '' : JSON.stringify(body).slice(0, 200),
      _verifier_failed: raw === ''
    })
  };
});

// Everything that could not be verified: no verifier key set, no address to check, or an
// organisation Apollo found nobody at. It is still written to the sheet — the work is not
// thrown away — it just never reaches the sending list while HOLD_UNVERIFIED is true.
//
// DEMO_VERIFIER gives these a deterministic pretend verdict so the rest of the pipeline can
// be watched on a screen-share. The config node forces preview whenever that is on, so a
// made-up verdict cannot reach a real campaign.
const cfg = $('config').first().json;
const stamp = new Date().toISOString().slice(0, 16).replace('T', ' ');

// Same address always gets the same fake verdict, so a demo is repeatable.
const pretend = (email) => {
  let h = 0;
  for (const ch of String(email)) h = (h * 31 + ch.charCodeAt(0)) % 100000;
  const n = h % 100;
  if (n < 78) return 'ok';
  if (n < 90) return 'catch_all';
  if (n < 96) return 'unknown';
  return 'invalid';
};

return $input.all().map((item) => {
  const c = item.json;

  if (c._no_contact) {
    return {
      json: Object.assign({}, c, {
        email_status: '', _verdict: 'no contact', _verified: false, _verified_at: ''
      })
    };
  }

  if (cfg.demo_verdicts) {
    const status = pretend(c.email);
    const verdict = (cfg.accept_statuses || []).includes(status) ? 'accepted'
      : ((cfg.risky_statuses || []).includes(status) ? 'risky' : 'rejected');
    return {
      json: Object.assign({}, c, {
        email_status: status + ' (demo)',
        _verdict: verdict,
        _verified: verdict === 'accepted',
        _verified_at: stamp,
        _demo_verdict: true
      })
    };
  }

  return {
    json: Object.assign({}, c, {
      email_status: 'unverified',
      _verdict: 'unverified',
      _verified: false,
      _verified_at: '',
      _hold_reason: c._hold_reason || 'not verified'
    })
  };
});

// The one gate that decides who gets emailed. Every reason a contact is held is written on
// the contact, in words, so the sheet answers "why isn't this person in the campaign?"
// without anyone having to open an execution log.
//
// Order matters: the cheapest and most absolute rules run first, so a suppressed address is
// never reported as merely low-scoring.
const cfg = $('config').first().json;
const contacts = $input.all().map((i) => i.json);

const suppression = cfg.suppression || [];
const rolePrefixes = (cfg.role_prefixes || []).map((p) => String(p).toLowerCase());
const minScore = Number(cfg.min_icp_score || 0);
const cap = Number(cfg.daily_cap || 0);
const requireState = String(cfg.require_state || '');

const seenEmail = new Set();
let pushed = 0;

const decided = contacts.map((c) => {
  const email = String(c.email || '').trim().toLowerCase();
  const domain = email.split('@')[1] || '';
  const local = email.split('@')[0] || '';

  let hold = '';

  if (c._no_contact) hold = c._hold_reason || 'no contact found';
  else if (!email.includes('@')) hold = 'no email address';
  else if (c.tier === 'X') hold = c._hold_reason || 'excluded title';
  else if (suppression.some((s) => s === email || s === domain || domain.endsWith('.' + s))) hold = 'on the suppression list';
  else if (seenEmail.has(email)) hold = 'duplicate of another row this run';
  else if (rolePrefixes.includes(local) || c._verifier_role_flag) hold = 'shared mailbox, not a person';
  else if (requireState && String(c.state || '').toUpperCase() !== requireState) hold = 'outside ' + requireState;
  else if (c._verdict === 'rejected') hold = 'verifier says ' + (c.email_status || 'undeliverable');
  else if (c._verdict === 'risky') hold = 'risky (' + (c.email_status || 'catch-all') + ')';
  else if (!c._verified && cfg.hold_unverified) hold = c._verdict === 'unverified' ? 'not verified yet' : 'not verified';
  else if (Number(c.score || 0) < minScore) hold = 'ICP score ' + Number(c.score || 0) + ' below ' + minScore;

  if (!hold && email) seenEmail.add(email);

  // The cap is enforced here, in code, not described in a comment somewhere.
  if (!hold && cap > 0 && pushed >= cap) hold = 'daily cap of ' + cap + ' reached';
  if (!hold) pushed++;

  const campaign = (cfg.campaign_by_category || {})[c.category] || cfg.campaign_id || '';

  return Object.assign({}, c, {
    _safe: hold === '',
    _hold_reason: hold,
    _campaign_id: hold === '' ? campaign : '',
    sending_list: hold === '' ? 'Yes' : 'No'
  });
});

const safe = decided.filter((c) => c._safe);
const withEmail = decided.filter((c) => !c._no_contact && String(c.email || '').includes('@'));
const rejected = decided.filter((c) => c._verdict === 'rejected').length;

// The numbers the KPI conversation actually needs. Reported per run, on every item, so the
// summary node and the sheet cannot disagree about them.
const stats = {
  _contacts_seen: decided.length,
  _with_email: withEmail.length,
  _safe_count: safe.length,
  _held_count: decided.length - safe.length,
  _rejected_count: rejected,
  _verified_rate: withEmail.length ? Math.round((withEmail.filter((c) => c._verified).length / withEmail.length) * 100) : 0,
  // What the bounce rate would have been had nothing been filtered.
  _bounce_risk_avoided: withEmail.length ? Math.round((rejected / withEmail.length) * 1000) / 10 : 0,
  _any_safe: safe.length > 0 && cfg.push_enabled === true
};

return decided.map((c) => ({
  json: Object.assign({}, c, stats, { _push: c._safe && cfg.push_enabled === true })
}));

// One row per organisation, folded back from however many contacts came out of it, so the
// raw list records what happened and the next run does not do the same work again.
//
// The status is the honest one: "Enriched" only if a person with an address came out,
// "No contact found" otherwise. An org that silently looks done but produced nobody is how
// a 2,000-record database turns out to contain 900 usable people.
const cfg = $('config').first().json;
const C = cfg.org_columns;
const contacts = $input.all().map((i) => i.json);
const stamp = new Date().toISOString().slice(0, 16).replace('T', ' ');

// Carried onto every org row so the gates further down have something run-level to read
// after the item shape has changed from contacts to organisations.
const runFlags = {
  _contacts_to_write: contacts.some((c) => !c._no_contact && String(c.email || '').includes('@')),
  _any_safe: contacts.some((c) => c._safe) && cfg.push_enabled === true
};

const byOrg = new Map();
for (const c of contacts) {
  const id = c.org_id || '(unknown)';
  if (!byOrg.has(id)) byOrg.set(id, []);
  byOrg.get(id).push(c);
}

const rows = [];

for (const [id, group] of byOrg) {
  const first = group[0] || {};
  const found = group.filter((c) => !c._no_contact && String(c.email || '').includes('@'));
  const safe = group.filter((c) => c._safe);

  const notes = [];
  if (first._category_matched_on === 'ai') notes.push('category by AI: ' + (first._ai_answer || ''));
  if (first._domain_missing) notes.push('no website on the raw row');
  if (first._apollo_hidden) notes.push(first._apollo_hidden + ' Apollo emails locked');
  if (!found.length) notes.push(first._hold_reason || 'no contact found');
  else if (!safe.length) notes.push('found ' + found.length + ', none passed: ' + (found[0]._hold_reason || ''));

  const row = {};
  row[C.org_id]      = id;
  row[C.name]        = first.org_name || '';
  row[C.category]    = first.category || '';
  row[C.website]     = first.domain || '';
  row[C.county]      = first.county || '';
  row[C.city]        = first.city || '';
  row[C.state]       = first.state || '';
  row[C.phone]       = first.phone || '';
  row[C.source]      = first.source || '';
  row[C.status]      = found.length ? 'Enriched' : 'No contact found';
  row[C.enriched_at] = stamp;
  row[C.contacts]    = found.length;
  row[C.notes]       = notes.join(' | ').slice(0, 900);

  rows.push({ json: Object.assign({}, row, runFlags, { _org_id: id, _contacts: group.length }) });
}

return rows;

// The organisations were worked but nobody usable came out of any of them. The
// Organisations tab has already been updated with the reason per row, so the next run does
// not grind through the same dead addresses.
//
// Seeing this branch fire repeatedly means the raw list is the problem, not the pipeline —
// usually scraped rows with no website, or an Apollo plan out of credits.
const contacts = $('decide who is safe to email').all().map((i) => i.json);

const reasons = {};
for (const c of contacts) {
  const r = c._hold_reason || 'unknown';
  reasons[r] = (reasons[r] || 0) + 1;
}

return [{
  json: {
    _outcome: 'no contacts found',
    organisations_worked: new Set(contacts.map((c) => c.org_id)).size,
    reasons: reasons,
    _next_step: 'Check the Website column on those rows, and Apollo credits.'
  }
}];

// One row per contact, in the same shape every time.
//
// The contacts come from "decide who is safe to email" rather than from this node's input,
// because the input is now organisation rows — the previous step folded them. Held contacts
// are written too, with the reason in plain words: the sheet is the record of the whole
// database, not just the part that got emailed.
const cfg = $('config').first().json;
const C = cfg.contact_columns;
const stamp = new Date().toISOString().slice(0, 16).replace('T', ' ');

const contacts = $('decide who is safe to email').all()
  .map((i) => i.json)
  .filter((c) => !c._no_contact && String(c.email || '').includes('@'));

return contacts.map((c) => {
  const row = {};
  row[C.contact_id]   = c.contact_id || '';
  row[C.org_id]       = c.org_id || '';
  row[C.org_name]     = c.org_name || '';
  row[C.category]     = c.category || '';
  row[C.county]       = c.county || '';
  row[C.full_name]    = c.full_name || '';
  row[C.first_name]   = c.first_name || '';
  row[C.title]        = c.title || '';
  row[C.email]        = c.email || '';
  row[C.email_status] = c.email_status || '';
  row[C.verified_at]  = c._verified_at || '';
  row[C.phone]        = c.contact_phone || '';
  row[C.linkedin]     = c.linkedin || '';
  row[C.score]        = Number(c.score || 0);
  row[C.tier]         = c.tier || '';
  row[C.sending_list] = c.sending_list || 'No';
  row[C.hold_reason]  = c._hold_reason || '';
  row[C.updated_at]   = stamp;
  // Campaign and "Pushed at" are deliberately absent. This write matches on Contact id, and
  // a blank here would wipe what a previous run recorded; only "mark them pushed" sets them.

  return { json: Object.assign({}, row, { _contact: c }) };
});

// Build one Instantly lead per safe contact, and only the safe ones.
//
// The custom variables are the reason the email can be short and specific — {{firstName}},
// {{organisation}} and {{county}} are what let one sequence read as though it were written
// for a discharge planner in Franklin County rather than mail-merged at 2,000 people.
const cfg = $('config').first().json;

const contacts = $('decide who is safe to email').all()
  .map((i) => i.json)
  .filter((c) => c._push === true);

return contacts.map((c) => ({
  json: {
    _body: {
      campaign: c._campaign_id || cfg.campaign_id,
      email: c.email,
      first_name: c.first_name || '',
      last_name: String(c.full_name || '').split(/\s+/).slice(1).join(' '),
      company_name: c.org_name || '',
      personalization: c.first_name || 'there',
      phone: c.contact_phone || '',
      website: c.domain || '',
      custom_variables: {
        organisation: c.org_name || '',
        county: c.county || '',
        city: c.city || '',
        segment: c.category || '',
        title: c.title || '',
        icp_score: Number(c.score || 0),
        tier: c.tier || '',
        email_status: c.email_status || '',
        org_id: c.org_id || '',
        contact_id: c.contact_id || ''
      },
      skip_if_in_workspace: true,
      verify_leads_on_import: false
    },
    _contact_id: c.contact_id,
    _email: c.email,
    _campaign_id: c._campaign_id || cfg.campaign_id,
    _mode: cfg.mode
  }
}));

// Write back only what the sending engine actually accepted.
//
// A lead Instantly rejected — already in another campaign, blocked, malformed — must not be
// recorded as pushed, or the next run will think it is handled and the person is never
// contacted by anyone. The failure is written into the hold reason instead.
const cfg = $('config').first().json;
const C = cfg.contact_columns;
const src = $('payload for the campaign');
const replies = $input.all();
const stamp = new Date().toISOString().slice(0, 16).replace('T', ' ');

const sentFor = (i) => {
  try { return src.itemMatching(i).json; } catch (e) { /* fall through */ }
  return (src.all()[i] || { json: {} }).json;
};

return replies.map((reply, i) => {
  const sent = sentFor(i);
  const body = reply.json || {};

  // Instantly v2 returns the created lead with an id. Anything else is a failure.
  const ok = Boolean(body.id || body.lead_id || body.status === 'success');
  const error = String(body.error || body.message || (body.detail && body.detail.message) || '').slice(0, 200);

  const row = {};
  row[C.contact_id]   = sent._contact_id || '';
  row[C.email]        = sent._email || '';
  row[C.sending_list] = ok ? 'Yes' : 'No';
  row[C.campaign]     = ok ? (sent._campaign_id || '') : '';
  row[C.pushed_at]    = ok ? stamp : '';
  row[C.hold_reason]  = ok ? '' : ('campaign rejected it: ' + (error || 'unknown error'));
  row[C.updated_at]   = stamp;

  return {
    json: Object.assign({}, row, {
      _ok: ok, _email: sent._email, _error: error
    })
  };
});

// Nothing was pushed to a campaign this run. Open this node to see why, per contact.
//
// In preview mode — how the workflow ships — this is where every run lands, and its output
// is the review screen: name, title, score, verifier verdict and hold reason for everyone
// the pipeline touched. Read it before turning the sending gate on.
const cfg = $('config').first().json;

const reason = cfg.forced_preview
    ? 'forced to preview: DEMO_VERIFIER is on, so the verdicts are not real'
  : cfg.preview_only
    ? 'preview mode — TEST_RUN is true and TEST_CAMPAIGN_ID is blank'
  : !cfg.instantly_api_key
    ? 'no Instantly API key in config'
  : !cfg.campaign_id
    ? 'no campaign id in config'
    : 'nothing passed verification and scoring this run';

return $('decide who is safe to email').all().map((i) => {
  const c = i.json;
  return {
    json: {
      _outcome: 'not pushed',
      _why: reason,
      organisation: c.org_name,
      name: c.full_name || '(no contact found)',
      title: c.title || '',
      email: c.email || '',
      email_status: c.email_status || '',
      score: c.score,
      tier: c.tier,
      would_be_sent: Boolean(c._safe),
      hold_reason: c._hold_reason || '',
      campaign_it_would_go_to: c._campaign_id || cfg.campaign_id || '(none set)'
    }
  };
});

// The one screen that says whether the pipeline is healthy: how many organisations were
// worked, how many people came out, what the verifier threw away, and how many reached the
// campaign — plus the number the client is actually judged on, the share of the sending
// list that is verified deliverable.
const cfg = $('config').first().json;
const contacts = $('decide who is safe to email').all().map((i) => i.json);
const first = contacts[0] || {};

let pushedOk = 0;
let pushedFailed = 0;
let pushErrors = [];
try {
  for (const item of $('record what was pushed').all()) {
    if (item.json._ok) pushedOk++;
    else { pushedFailed++; if (item.json._error) pushErrors.push(item.json._error); }
  }
} catch (e) {
  // The push branch did not run this time. Preview runs land here every time.
}

const orgs = new Set(contacts.map((c) => c.org_id)).size;
const withEmail = contacts.filter((c) => !c._no_contact && String(c.email || '').includes('@'));
const held = contacts.filter((c) => !c._safe);

const reasons = {};
for (const c of held) {
  const r = c._hold_reason || 'unknown';
  reasons[r] = (reasons[r] || 0) + 1;
}
const topReasons = Object.keys(reasons)
  .sort((a, b) => reasons[b] - reasons[a])
  .slice(0, 6)
  .map((r) => reasons[r] + ' x ' + r);

const bySegment = {};
for (const c of contacts.filter((x) => x._safe)) {
  bySegment[c.category] = (bySegment[c.category] || 0) + 1;
}

const batch = $('pick this run\'s batch').first().json || {};

const lines = [
  'the partnership partnership engine — enrich and verify',
  'Mode: ' + cfg.mode.toUpperCase() + (cfg.forced_preview ? ' (forced: demo verdicts are on)' : ''),
  '',
  'Organisations worked: ' + orgs + ' of ' + (batch._rows_in_sheet || 0) + ' rows in the sheet',
  'Contacts found: ' + withEmail.length + ' (' + (withEmail.length && orgs ? (Math.round((withEmail.length / orgs) * 10) / 10) : 0) + ' per org)',
  'Verified deliverable: ' + withEmail.filter((c) => c._verified).length + ' (' + (first._verified_rate || 0) + '%)',
  'Undeliverable caught: ' + (first._rejected_count || 0) + ' — that is ' + (first._bounce_risk_avoided || 0) + '% of bounce risk removed before sending',
  'Onto the sending list: ' + (first._safe_count || 0),
  'Held back: ' + held.length,
  '',
  'Why they were held: ' + (topReasons.length ? topReasons.join(', ') : 'nothing held'),
  'Sending list by segment: ' + (Object.keys(bySegment).length
    ? Object.keys(bySegment).map((k) => k + ' ' + bySegment[k]).join(', ') : 'none'),
  '',
  cfg.push_enabled
    ? 'Pushed to campaign: ' + pushedOk + ' ok, ' + pushedFailed + ' rejected'
      + (pushErrors.length ? ' (' + pushErrors.slice(0, 2).join('; ') + ')' : '')
    : 'Pushed to campaign: nothing — ' + (cfg.preview_only ? 'preview mode' : 'sending engine not configured')
];

// Anything here needs a human before the next run.
const warnings = [];
if (!cfg.verifier_enabled) warnings.push('no verifier key: every address is being held');
if (!cfg.apollo_enabled) warnings.push('no Apollo key: running on sheet contacts only');
if (cfg.demo_verdicts) warnings.push('DEMO_VERIFIER is on — verdicts are fabricated');
if (withEmail.length && (first._verified_rate || 0) < 60) warnings.push('verified rate under 60% — check the source of this list');
if (pushedFailed > pushedOk && pushedFailed > 0) warnings.push('more campaign rejections than successes');
if (warnings.length) lines.push('', 'Needs attention: ' + warnings.join(' | '));

const text = lines.join('\n');

return [{
  json: {
    summary_text: text,
    orgs_worked: orgs,
    contacts_found: withEmail.length,
    verified: withEmail.filter((c) => c._verified).length,
    verified_rate: first._verified_rate || 0,
    undeliverable_caught: first._rejected_count || 0,
    sending_list: first._safe_count || 0,
    held: held.length,
    pushed_ok: pushedOk,
    pushed_failed: pushedFailed,
    hold_reasons: reasons,
    warnings: warnings,
    mode: cfg.mode,
    // Slack incoming-webhook shape. Any webhook that accepts JSON will take this.
    _alert_body: { text: text }
  }
}];
